# The landing page: static files from the checkout's landing/, so every deploy
# updates it. Unset, it falls back to an unpublished port and serves nothing.
{$LANDING_ADDRESS::8081} {
	encode zstd gzip
	root * /srv/landing
	# landing/ also holds CLAUDE.md and export_data.py; publish only the page.
	@private not path / /index.html /app/*
	respond @private 404
	file_server
}

